public class TbCashHis { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="CASH_HIS_ID") private Long cashHistoryId; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="ACCT_ID",nullable=false) private TbAcct account; @ManyToOne(fetch=FetchType.LAZY) @JoinColumns({@JoinColumn(name="REG_BUY_ACCT_TP",referencedColumnName="ACCT_TP"),@JoinColumn(name="REG_BUY_STK_CD",referencedColumnName="STK_CD")}) private TbRegBuy regularBuy; @Column(name="TX_DT",nullable=false) private LocalDate transactionDate; @Enumerated(EnumType.STRING) @Column(name="CASH_TP",nullable=false,length=20) private CashType cashType; @Enumerated(EnumType.STRING) @Column(name="TX_TP",nullable=false,length=30) private CashTransactionType transactionType; @Enumerated(EnumType.STRING) @Column(name="IN_OUT_TP",nullable=false,length=10) private InOutType inOutType; @Column(name="TX_AMT",nullable=false,precision=20,scale=4) private BigDecimal transactionAmount; @Column(name="BAL_BFR_AMT",nullable=false,precision=20,scale=4) private BigDecimal balanceBeforeAmount; @Column(name="BAL_AFT_AMT",nullable=false,precision=20,scale=4) private BigDecimal balanceAfterAmount; @Column(name="IDEMP_KEY",nullable=false,length=100) private String idempotencyKey; @Column(name="REF_TBL_NM",length=50) private String referenceTableName; @Column(name="REF_ID") private Long referenceId; @Column(name="TX_RSN",length=500) private String transactionReason; @Column(name="CRT_DTTM",insertable=false,updatable=false) private OffsetDateTime createdDateTime; @Column(name="CRT_USR_ID",length=50) private String createdUserId; }

